BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Addressee of the management representation letter
(1, 'Written Representations', 'Under AU-C 580, the management representation letter is addressed to:', '["The auditor or the engagement partner", "The audit committee chairperson", "The entity''s board of directors", "The SEC or applicable regulatory body"]'::jsonb, 0, 'Under AU-C 580.09, the management representation letter is addressed to the auditor. The letter is a direct communication from management confirming matters discussed during the audit and supporting other audit evidence. While the audit committee oversees the audit process, the representation letter is not addressed to the audit committee — it is management''s written confirmation provided specifically to the engagement partner or the auditor.', 'easy', 1),

-- Q2: easy / L1 — Form of written representations
(1, 'Written Representations', 'Under AU-C 580, written representations from management should be provided in the form of:', '["An oral statement recorded in the audit workpapers", "A written letter addressed to the auditor", "A notarized affidavit filed with the court", "A formal resolution adopted by the board of directors"]'::jsonb, 1, 'Under AU-C 580.05, management''s written representations must take the form of a representation letter addressed to the auditor. Oral representations, while potentially useful during the audit, do not satisfy the requirement for written representations because they lack the formality and documentation needed to serve as reliable audit evidence. The letter provides a written record that management has acknowledged specific responsibilities and confirmed specific assertions.', 'easy', 1),

-- Q3: medium / L2 — Representation about uncorrected misstatements
(1, 'Written Representations', 'During the audit of Kensington Dynamics for the year ended December 31, 2025, the engagement team at Powell & Sterling CPA identified $38,000 in aggregate uncorrected misstatements. Overall materiality is $75,000. Management declines to correct these items. Under AU-C 580, the management representation letter should include:', '["A statement that management will correct all identified misstatements in the subsequent period", "A commitment that the uncorrected misstatements will be disclosed in the notes to the financial statements", "A representation that management believes the uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole", "A waiver releasing the auditor from liability related to the uncorrected misstatements"]'::jsonb, 2, 'Under AU-C 580.11, management must represent that uncorrected misstatements identified during the audit are immaterial, both individually and in the aggregate, to the financial statements as a whole. The auditor attaches a summary of these items to the representation letter. Although choice A suggests correcting misstatements in a future period, this does not satisfy the current-period representation requirement — the letter must address the immateriality of uncorrected items as of the report date.', 'medium', 2),

-- Q4: medium / L3 — Effect of management inability to provide an additional (non-required) representation
(1, 'Written Representations', 'The audit team at Hartfield & Lane is auditing Crestwood Enterprises for the year ended December 31, 2025. The auditor requested an additional written representation about management''s assessment of cybersecurity risk controls. Management states it cannot provide this representation because no formal assessment was performed. Under AU-C 580, how does management''s inability to provide this additional requested representation affect the audit?', '["The auditor must issue a disclaimer of opinion because all requested representations must be provided", "The auditor must withdraw from the engagement due to a scope limitation", "The auditor must issue a qualified opinion citing the lack of representation", "The auditor should consider the implications for the audit but is not required to modify the opinion solely because an additional requested representation was not provided"]'::jsonb, 3, 'Under AU-C 580.14, a disclaimer of opinion is required only when management refuses to provide one or more of the specifically required representations enumerated in the standard. For additional requested representations beyond those required by AU-C 580, the auditor evaluates the implications but is not automatically required to modify the opinion. However, choice A incorrectly treats all auditor-requested representations as mandatory, when only the representations specifically required by AU-C 580 trigger a disclaimer if refused.', 'medium', 3),

-- Q5: medium / L2 — Representation about compliance with laws and regulations
(1, 'Written Representations', 'Lexington Financial Services is completing its December 31, 2025 audit with Harper & Caldwell CPA. The controller asks which compliance-related representation must appear in the management representation letter. Under AU-C 580, management is required to represent that:', '["All known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered when preparing the financial statements have been disclosed to the auditor", "The entity has complied with all applicable laws and regulations without exception", "Management has obtained legal opinions confirming compliance with all material regulations", "An independent compliance officer has certified the entity''s regulatory standing"]'::jsonb, 0, 'Under AU-C 580.11, management must represent that all known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered when preparing the financial statements have been disclosed to the auditor. However, choice B overstates the requirement — AU-C 580 requires disclosure of known noncompliance, rather than a blanket certification of full compliance, which would be unreasonably broad.', 'medium', 2),

-- Q6: medium / L2 — Representation about subsequent events in the letter
(1, 'Written Representations', 'Morrison & Blake CPA is finalizing the audit of Silverline Technologies for the year ended December 31, 2025. The auditor''s report is dated March 12, 2026. The engagement partner reminds the controller to include a subsequent events representation in the management representation letter. Under AU-C 580, this representation should confirm that:', '["No events occurred between the balance sheet date and the report date", "All events occurring between the balance sheet date and the date of the representation letter that require adjustment or disclosure have been adjusted or disclosed", "The auditor has sole responsibility for identifying subsequent events requiring disclosure", "Management has hired an independent consultant to evaluate all subsequent events"]'::jsonb, 1, 'Under AU-C 580.11, management must represent that all subsequent events occurring between the balance sheet date and the date of the management representation letter that require adjustment or disclosure have been properly addressed. Choice A is incorrect because it asserts no events occurred at all, which is an unrealistic and overly broad claim — the standard requires disclosure of events needing adjustment or disclosure, not a blanket denial of post-balance-sheet activity.', 'medium', 2),

-- Q7: easy / L1 — Period covered by the management representation letter
(1, 'Written Representations', 'Under AU-C 580, the management representation letter covers:', '["Only the current fiscal year under audit", "Only the period from the interim date through year-end", "All periods referred to in the auditor''s report", "Only the subsequent events period after the balance sheet date"]'::jsonb, 2, 'Under AU-C 580.09, the management representation letter covers all periods referred to in the auditor''s report. When the auditor''s report covers comparative financial statements, management''s representations apply to all periods presented. Choice A is incorrect because limiting representations to only the current year would leave prior-period assertions unaddressed when comparative statements are included in the auditor''s report.', 'easy', 1),

-- Q8: medium / L2 — Representation about plans or intentions affecting carrying values
(1, 'Written Representations', 'During the audit of Ridgecrest Manufacturing for the year ended December 31, 2025, the engagement team at Whitmore & Associates discovers that management plans to discontinue a product line in mid-2026. The carrying value of related inventory is $1.2 million. Under AU-C 580, the management representation letter should include a representation about:', '["The auditor''s agreement with management''s decision to discontinue the product line", "The exact date management will complete the discontinuation", "The third-party appraisal value of the inventory to be discontinued", "Plans or intentions that may affect the carrying value or classification of assets and liabilities"]'::jsonb, 3, 'Under AU-C 580.11, management must represent that it has disclosed all plans or intentions that may materially affect the carrying value or classification of assets and liabilities. Discontinuing a product line could impair inventory values and trigger write-downs. Choice C is incorrect because AU-C 580 does not require a third-party appraisal — the representation concerns disclosure of plans and intentions, not independent valuation of affected assets.', 'medium', 2),

-- Q9: medium / L3 — Analyzing whether oral representations substitute for written
(1, 'Written Representations', 'During the audit of Thornbridge Capital for the year ended December 31, 2025, the CFO verbally confirms to the engagement team at Prescott & Associates that all material litigation has been disclosed. The CFO suggests this oral confirmation should satisfy the representation requirement without a formal letter. Under AU-C 580, what is the effect of relying solely on oral representations?', '["Oral representations do not substitute for required written representations, and the auditor cannot rely on them in place of the management representation letter", "Oral representations are acceptable if documented in the audit workpapers by two members of the engagement team", "Oral representations carry the same evidentiary weight as written representations when provided by the CFO", "Oral representations are preferred because they allow for real-time follow-up questions"]'::jsonb, 0, 'Under AU-C 580.05, written representations are required and oral statements cannot substitute for them. The standard specifically requires management''s representations to be in written form because written representations provide a more reliable and formal record than oral statements. Although choice B suggests documenting an oral statement in the workpapers, this does not satisfy the explicit requirement for a written representation letter under AU-C 580.', 'medium', 3),

-- Q10: easy / L1 — Representation about access to all records and personnel
(1, 'Written Representations', 'Under AU-C 580, management must represent that it has provided the auditor with:', '["Copies of all correspondence with regulatory agencies", "Access to all information relevant to the preparation of the financial statements, including records, documentation, and personnel", "A complete list of all vendors and customers with contact details", "Audited financial statements from all related entities"]'::jsonb, 1, 'Under AU-C 580.11, management must represent that it has provided the auditor with access to all information that management believes is relevant to the preparation and fair presentation of the financial statements. This includes records, documentation, and personnel. Choice A is too narrow — while regulatory correspondence may be relevant, the required representation broadly covers all relevant information, not just regulatory correspondence.', 'easy', 1),

-- Q11: hard / L3 — Representations contradicted by other audit evidence
(1, 'Written Representations', 'During the audit of Blackstone Ventures for the year ended December 31, 2025, the engagement team at Crawford & Ellis obtains a management representation letter stating that all related-party transactions have been disclosed. However, the auditor''s independent analysis of bank records reveals a $450,000 loan to an entity controlled by the CEO''s spouse that was not disclosed. Under AU-C 580, what is the most likely implication of this inconsistency?', '["The auditor should accept the representation as conclusive and disregard the bank record findings", "The auditor should request management to amend the letter to exclude the related-party assertion", "The auditor should reconsider the reliability of all management representations and evaluate the effect on the audit opinion", "The auditor should issue the report with an emphasis-of-matter paragraph noting the inconsistency"]'::jsonb, 2, 'Under AU-C 580.17, when written representations are inconsistent with other audit evidence, the auditor must perform additional procedures to resolve the matter. If the inconsistency raises doubt about the reliability of representations, the auditor must reconsider whether reliance on management''s representations as a whole is appropriate and evaluate the effect on the audit opinion. Choice A is incorrect because written representations never override contradictory audit evidence — professional skepticism requires investigation.', 'hard', 3),

-- Q12: medium / L2 — Representation about completeness of litigation and claims
(1, 'Written Representations', 'The engagement team at Langford & Associates is finalizing the audit of Pinnacle Health Systems for the year ended December 31, 2025. The partner requests that management include a representation about litigation in the representation letter. Under AU-C 580, management should represent that:', '["The entity has never been involved in any litigation or regulatory proceedings", "All litigation has been resolved favorably prior to year-end", "Management''s outside legal counsel has confirmed a favorable outcome for all pending cases", "All known actual or possible litigation and claims whose effects should be considered in the financial statements have been disclosed to the auditor"]'::jsonb, 3, 'Under AU-C 580.11, management must represent that all known actual or possible litigation and claims whose effects should be considered when preparing the financial statements have been disclosed to the auditor. This includes both pending and threatened litigation. Choice B is incorrect because the representation requires disclosure of all known litigation and claims regardless of status — unresolved litigation must still be disclosed for proper financial statement evaluation.', 'medium', 2),

-- Q13: medium / L3 — Analyzing representation about accounting estimates and assumptions
(1, 'Written Representations', 'During the audit of Westlake Properties for the year ended December 31, 2025, the engagement team at Aldridge & Harris reviews management''s allowance for doubtful accounts estimate. Management used a 3% default rate based on historical experience, while industry data suggests 5% may be more appropriate. Under AU-C 580, how should the management representation letter address accounting estimates?', '["Management should represent that the auditor selected the assumptions used in the estimate", "Management should represent that it used the industry-standard rate rather than its own data", "Management should represent that all recorded estimates will exactly match actual outcomes", "Management should represent that the methods, data, and significant assumptions used in making accounting estimates are reasonable in the context of the applicable financial reporting framework"]'::jsonb, 3, 'Under AU-C 580.11, management must represent that the methods, significant assumptions, and data used in making accounting estimates are reasonable in the context of the applicable financial reporting framework. Management owns its estimates and must stand behind their reasonableness. Choice A is incorrect because the auditor does not select assumptions for management — management is responsible for its own estimates, and the representation confirms management''s ownership of those judgments.', 'medium', 3),

-- Q14: hard / L4 — Evaluating withdrawal of a required representation before report release
(1, 'Written Representations', 'On March 8, 2026, the engagement team at Greystone & Partners receives the signed management representation letter from Brookfield Industries for its December 31, 2025 audit. The letter is dated March 8, matching the auditor''s report date. On March 12, before the report is released, management sends a revised letter removing the representation about completeness of related-party disclosures, citing uncertainty. Under AU-C 580, what is the most appropriate course of action?', '["The auditor should treat the withdrawal of the required representation as a scope limitation and consider the effect on the audit opinion, including a possible disclaimer", "The auditor should accept the revised letter because management has the right to modify representations at any time before report release", "The auditor should issue the report using the original letter since it was already signed", "The auditor should request that the audit committee override management''s revision"]'::jsonb, 0, 'Under AU-C 580.14, if management does not provide one or more of the required written representations, the auditor must discuss the matter with management, reevaluate the integrity of management, and determine the effect on the opinion, which may include a disclaimer. Withdrawing a previously provided required representation has the same effect as refusing to provide it. Choice C is incorrect because the auditor cannot rely on a superseded letter — the most recent communication from management governs.', 'hard', 4),

-- Q15: hard / L4 — Component management representations in group audit
(1, 'Written Representations', 'The group engagement partner at Holloway & Associates is auditing the consolidated financial statements of Meridian Holdings for the year ended December 31, 2025. Meridian has three wholly owned subsidiaries, each audited by component auditors. The group engagement partner considers whether separate management representation letters are needed from each subsidiary''s management. Under AU-C 580 and AU-C 600, what is the most appropriate approach?', '["Only the parent company''s management representation letter is needed because it covers all consolidated entities", "The group engagement team should obtain written representations from group management and, as appropriate, from component management regarding matters relevant to the group financial statements", "Component management representations are only required when the subsidiaries operate in foreign jurisdictions", "The component auditors'' reports substitute for component management representation letters"]'::jsonb, 1, 'Under AU-C 600.40 and AU-C 580, the group engagement partner should obtain written representations from group management and, when appropriate, from component management on matters relevant to the group financial statements. This ensures representations cover subsidiary-specific matters that group management may not have direct knowledge of. Choice A is incorrect because parent management may lack sufficient knowledge of component-specific transactions and balances, making component-level representations necessary for adequate coverage.', 'hard', 4),

-- Q16: hard / L4 — Evaluating impact of management change on ability to provide representations
(1, 'Written Representations', 'Ashworth & Klein CPA is auditing Cascade Innovations for the year ended December 31, 2025. The newly appointed CEO, who joined in November 2025, states she cannot represent transactions occurring before her tenure. The former CEO is unavailable. Under AU-C 580, what should the auditor evaluate when management asserts inability to provide representations due to limited tenure?', '["The auditor should accept a partial representation letter covering only the new CEO''s tenure", "The auditor should delay the report until the former CEO becomes available to co-sign", "The auditor should evaluate whether management''s inability constitutes a scope limitation and consider the effect on the audit opinion", "The auditor should issue an unmodified opinion because management changes do not affect representation requirements"]'::jsonb, 2, 'Under AU-C 580.16, if management does not provide requested written representations, the auditor must evaluate the implications. When new management cannot represent matters predating their tenure, the auditor assesses whether this constitutes a scope limitation and its effect on the opinion, and whether alternative evidence can compensate. Choice A is incorrect because AU-C 580 requires representations covering all periods in the auditor''s report, not just the current management''s tenure.', 'hard', 4),

-- Q17: easy / L1 — Written representations as necessary but not sufficient evidence
(1, 'Written Representations', 'Under AU-C 580, written representations from management provide what type of audit evidence?', '["Conclusive evidence that replaces the need for other audit procedures", "The most reliable form of audit evidence available to the auditor", "Evidence that eliminates the need for professional skepticism", "Necessary audit evidence, but not sufficient appropriate evidence on their own for any assertion"]'::jsonb, 3, 'Under AU-C 580.04, written representations are necessary audit evidence but do not provide sufficient appropriate audit evidence on their own about any of the matters they address. They complement other audit procedures but cannot replace substantive testing. Choice A is incorrect because representations are among the least reliable forms of evidence — they are internal, management-generated statements that require corroboration through independent audit procedures.', 'easy', 1),

-- Q18: easy / L2 — Who constitutes responsible management for AU-C 580
(1, 'Written Representations', 'Brennan & Cole CPA is auditing Westfield Logistics for the year ended December 31, 2025. The entity''s organizational structure includes a CEO, CFO, controller, and operations director. The engagement partner must determine who should sign the management representation letter. Under AU-C 580, responsible management includes:', '["Those with overall responsibility for financial and operating matters and knowledge of the matters covered by the representations", "Any employee who has access to the entity''s accounting and information systems", "Only the controller because that role prepares the financial statements", "The external legal counsel who advises on financial reporting matters"]'::jsonb, 0, 'Under AU-C 580.09, the auditor requests written representations from members of management who have appropriate responsibilities for, and knowledge of, the matters concerned — typically the CEO and CFO or their equivalents. Choice C is incorrect because while the controller may have detailed knowledge of financial statement preparation, AU-C 580 requires signatories with overall responsibility for both financial and operating matters, which typically extends beyond the controller role alone.', 'easy', 2),

-- Q19: easy / L1 — Representation about satisfactory title to assets
(1, 'Written Representations', 'Under AU-C 580, management should include a representation confirming that the entity has:', '["Satisfactory title to, or control over, all assets reported in the financial statements", "Insurance coverage for all recorded assets at replacement value", "Independent appraisals for all fixed assets on the balance sheet", "Written approval from lenders for all asset acquisitions during the period"]'::jsonb, 0, 'Under AU-C 580.11, management must represent that the entity has satisfactory title to, or control over, all assets and that liabilities are properly recorded. This representation supports the rights and obligations assertion in the financial statements. Choice B is incorrect because insurance coverage, while a sound business practice, is not a required representation under AU-C 580 — the standard focuses on ownership and control of assets, not risk management.', 'easy', 1),

-- Q20: easy / L1 — Representation about the applicable financial reporting framework
(1, 'Written Representations', 'Under AU-C 580, management must represent its responsibility for preparing and fairly presenting the financial statements in accordance with:', '["Whatever framework the auditor considers most appropriate for the engagement", "The applicable financial reporting framework", "International Financial Reporting Standards regardless of jurisdiction", "The framework used by the entity''s largest competitor"]'::jsonb, 1, 'Under AU-C 580.10, management must represent its responsibility for the preparation and fair presentation of the financial statements in accordance with the applicable financial reporting framework. This establishes management''s fundamental obligation underlying the audit. Choice A is incorrect because the framework is determined by management and applicable requirements, not by the auditor''s preference — the auditor evaluates the appropriateness of the selected framework but does not choose it.', 'easy', 1),

-- Q21: medium / L3 — Analyzing implications of representation letter dated before report date
(1, 'Written Representations', 'The engagement team at Fletcher & Monroe is auditing Oakmont Systems for the year ended December 31, 2025. The auditor''s report is dated March 15, 2026. Management signed and delivered the representation letter on March 10, 2026, five days before the report date. The engagement partner reviews the letter and notices the date discrepancy. Under AU-C 580, what is the implication of the representation letter being dated before the auditor''s report date?', '["The letter is acceptable because it was signed during the subsequent events period", "The earlier date is irrelevant because the representations are effective as of year-end only", "The auditor should request a new or updated representation letter dated as of the date of the auditor''s report", "The auditor should change the report date to match the representation letter date"]'::jsonb, 2, 'Under AU-C 580.09, the representation letter should be dated as of the date of the auditor''s report. A letter dated earlier does not cover the period between the letter date and the report date, creating a gap in management''s representations about subsequent events and other matters. Choice B is incorrect because while some representations relate to year-end balances, others — such as the subsequent events representation — must be current through the report date.', 'medium', 3),

-- Q22: medium / L2 — Representation about selection and application of accounting policies
(1, 'Written Representations', 'During the audit of Creston Medical Group for the year ended December 31, 2025, the engagement team at Whitley & Dean reviews the management representation letter. The partner notes that a representation about accounting policies is missing from the draft. Under AU-C 580, management should represent that:', '["The auditor selected all accounting policies on management''s behalf", "Only the audit committee is responsible for selecting accounting policies", "Accounting policies have remained unchanged from the prior year without exception", "The selection and application of accounting policies are appropriate and have been properly disclosed in the financial statements"]'::jsonb, 3, 'Under AU-C 580.11, management must represent that the selection and application of the entity''s accounting policies are appropriate. This includes confirmation that the policies are consistent with the applicable financial reporting framework and properly disclosed. Choice C is incorrect because the representation concerns the appropriateness and disclosure of policies, not whether they are unchanged — entities may adopt new policies when circumstances warrant, and such changes must also be properly disclosed.', 'medium', 2),

-- Q23: hard / L4 — Evaluating sufficiency of representations when internal controls are weak
(1, 'Written Representations', 'During the audit of Northwind Electronics for the year ended December 31, 2025, the engagement team at Jameson & Park identifies significant deficiencies in internal control over inventory valuation. Management''s representation letter asserts that inventory is stated at the lower of cost or net realizable value. The engagement partner must evaluate how much reliance to place on this representation given the control weaknesses. Under AU-C 580, what is the most appropriate conclusion?', '["Written representations about inventory valuation eliminate the need for further testing because management has accepted responsibility", "The representation letter provides sufficient evidence about inventory valuation regardless of the control environment", "The representation is unnecessary since the control deficiencies have already been communicated to governance", "The auditor should recognize that representations alone are insufficient and must obtain corroborating evidence through extended substantive procedures"]'::jsonb, 3, 'Under AU-C 580.04, written representations are necessary but not sufficient audit evidence on their own. When significant control deficiencies exist, the reliability of management-generated information — including representations — is reduced. The auditor must perform additional substantive procedures to corroborate management''s assertions about inventory valuation. Choice B is incorrect because AU-C 580 explicitly states representations cannot serve as the sole basis for audit conclusions, and weakened controls further diminish their evidentiary value.', 'hard', 4),

-- Q24: easy / L1 — Representation about known significant deficiencies in internal control
(1, 'Written Representations', 'Under AU-C 580, the management representation letter should include a representation confirming that management has disclosed to the auditor:', '["All employee performance evaluations from the current year", "All known deficiencies in internal control that management believes are significant", "The names of all employees who accessed the accounting system during the year", "A complete list of all passwords used in the entity''s information systems"]'::jsonb, 1, 'Under AU-C 580, management must represent that it has disclosed all known significant deficiencies in internal control. This supports the auditor''s responsibilities under AU-C 265 for evaluating and communicating internal control matters identified during the audit. Choice A is incorrect because employee performance evaluations are human resources matters outside the scope of AU-C 580, which focuses on representations directly relevant to the financial statements and the audit.', 'easy', 1),

-- Q25: medium / L2 — Representation requirements when entity has a change in management
(1, 'Written Representations', 'Dunbar & Associates is auditing Sterling Manufacturing for the year ended December 31, 2025. The CEO retired on September 30, 2025, and a new CEO was appointed on October 15, 2025. The new CEO signed the management representation letter on March 10, 2026. The engagement partner questions whether additional steps are necessary. Under AU-C 580, what should the auditor consider?', '["The auditor should evaluate whether the new CEO has sufficient knowledge to provide representations covering the full audit period and, if necessary, make additional inquiries or obtain representations from the former CEO", "The new CEO''s representations are automatically invalid because she was not in office for the entire audit period", "The auditor must obtain a separate letter from the retired CEO covering January through September 2025", "No additional steps are needed because the current CEO''s letter automatically covers the entire period"]'::jsonb, 0, 'Under AU-C 580, the auditor must determine whether the signatories have appropriate knowledge of the matters covered by the representations. When management changes during the audit period, the auditor evaluates whether new management can adequately represent matters for the full period. Choice D is incorrect because assuming the new CEO has full knowledge without evaluation could leave a gap — the auditor must assess whether additional inquiries or prior-management representations are necessary.', 'medium', 2),

-- Q26: medium / L2 — Representation about liens, pledges, and encumbrances on assets
(1, 'Written Representations', 'Trenton & Blake CPA is auditing Bayshore Development Corp. for the year ended December 31, 2025. Bayshore has $8.5 million in real estate holdings. The engagement partner reviews the management representation letter for completeness regarding asset assertions. Under AU-C 580, management should represent that:', '["All assets are fully insured at replacement value", "All real estate holdings have been independently appraised within the current year", "All liens, pledges, or encumbrances on assets have been disclosed in the financial statements", "The entity has received offers to purchase all major real estate holdings"]'::jsonb, 2, 'Under AU-C 580.11, management must represent that all liens, pledges, or encumbrances on assets, as well as assets pledged as collateral, have been properly disclosed. This supports the completeness and rights-and-obligations assertions for asset balances. Choice A is incorrect because insurance coverage is a risk management matter, not a financial statement assertion — AU-C 580 focuses on representations about matters that directly affect the financial statements.', 'medium', 2),

-- Q27: hard / L4 — Evaluating refusal to include required fraud representation
(1, 'Written Representations', 'The engagement partner at Hallmark & Pierce is finalizing the audit of Clearview Analytics for the year ended December 31, 2025. Management provides the signed representation letter but omits the representation about fraud, stating they find the request unnecessary because no fraud has ever occurred at the company. Management is otherwise cooperative and all other required representations are included. Under AU-C 580, what should the engagement partner recommend?', '["Accept the letter without the fraud representation because management''s cooperation indicates low fraud risk", "Issue a qualified opinion citing the missing fraud representation as a scope limitation", "Inform management that the fraud representation is required and that failure to include it may result in a disclaimer of opinion", "Obtain the fraud representation verbally and document it in the workpapers as a substitute"]'::jsonb, 2, 'Under AU-C 580.14-.15, the fraud representation is specifically required. If management refuses to provide any required representation, the auditor must discuss the matter with management and, if they still refuse, should disclaim an opinion. Choice A is incorrect because the absence of prior fraud does not eliminate the requirement — AU-C 580 mandates the fraud representation on every audit regardless of the entity''s history, as fraud may exist without management''s awareness.', 'hard', 4),

-- Q28: medium / L3 — Those charged with governance representations vs. management representations
(1, 'Written Representations', 'During the audit of Summit Healthcare Partners for the year ended December 31, 2025, the audit committee chairman asks the engagement team at Vance & Associates whether the audit committee should also provide written representations separate from management''s letter. Under AU-C 580, what is the relationship between representations from management and those from governance?', '["Written representations from those charged with governance replace the need for management''s letter", "Written representations are obtained from management; however, the auditor may also request representations from those charged with governance when considered appropriate", "Those charged with governance are prohibited from providing representations to avoid conflicts of interest", "Only those charged with governance can provide representations about related-party transactions"]'::jsonb, 1, 'Under AU-C 580.09, written representations are obtained from management. The auditor may also request written representations from those charged with governance when the auditor considers it appropriate, such as representations about governance oversight matters. Choice A is incorrect because governance representations supplement but do not replace management representations — management is directly responsible for the financial statements and must provide its own representations.', 'medium', 3),

-- Q29: medium / L3 — Effect of undisclosed side agreement on representation reliability
(1, 'Written Representations', 'After obtaining the signed management representation letter from Fieldstone Corp. for the year ended December 31, 2025, the engagement team at Carter & Sullivan discovers a side agreement between Fieldstone and a major customer that modifies revenue recognition terms for $2.1 million in recorded sales. The representation letter included a completeness assertion about revenue arrangements. Under AU-C 580, what is the primary concern?', '["Whether the undisclosed side agreement calls into question the reliability of management''s written representations and whether the financial statements may be materially misstated", "Whether the side agreement should be disclosed only in an emphasis-of-matter paragraph", "Whether the side agreement amount exceeds performance materiality before taking action", "Whether the customer involved will independently confirm the side arrangement"]'::jsonb, 0, 'Under AU-C 580.17, when the auditor discovers information contradicting written representations, the auditor must reconsider the reliability of management''s representations and evaluate whether the financial statements may be materially misstated. An undisclosed side agreement directly contradicts the completeness representation. Choice C is incorrect because even if the amount is below materiality, a deliberately undisclosed arrangement raises concerns about management integrity that affect the reliability of all representations.', 'medium', 3),

-- Q30: medium / L3 — Analyzing representation about completeness of minutes and records
(1, 'Written Representations', 'During the audit of Blackwell Industries for the year ended December 31, 2025, the engagement team at Donovan & Wells reviews management''s representation about completeness of corporate records. The auditor noticed that no board meeting minutes were provided for the October and November 2025 meetings, although meetings were scheduled. Under AU-C 580, what should the auditor analyze about this situation?', '["The missing minutes are irrelevant because board meetings are governance matters outside the financial statement audit scope", "The auditor should accept management''s oral explanation that nothing significant was discussed at those meetings", "The auditor should automatically issue an adverse opinion due to the missing documentation", "The missing minutes may indicate that management''s representation about completeness of information provided to the auditor is inaccurate, requiring additional procedures to evaluate the implications"]'::jsonb, 3, 'Under AU-C 580.17, when evidence is inconsistent with written representations, the auditor must reconsider their reliability. Missing board minutes, despite a completeness representation, may signal incomplete disclosure of matters affecting the financial statements, such as commitments, contingencies, or related-party transactions discussed at those meetings. Choice B is incorrect because oral explanations do not satisfy the auditor''s responsibility to independently evaluate whether the completeness representation is reliable.', 'medium', 3)
;

COMMIT;
